import { _decorator } from "cc";
const { ccclass, property } = _decorator;

@ccclass("SpeedConfig")
export class SpeedConfig {
    @property({ tooltip: "啟動間隔 (毫秒)" })
    spinInterval: number = 100;

    @property({ tooltip: "停止間隔 (毫秒)" })
    stopInterval: number = 180;

    @property({ tooltip: "加速時間 (秒)" })
    beginDuration: number = 0.5;

    @property({ tooltip: "每格時間 (秒)" })
    loopTime: number = 0.05;

    @property({ tooltip: "減速時間 (秒)" })
    endDuration: number = 0.1;

    @property({ tooltip: "最短轉動時間 (毫秒)" })
    spinTime: number = 1000;
}
