import { isMock } from '../../../../base/config/GameConfig';
import AppConfig from './Config/AppConfig';
import AppUtility from '../../../../base/utility/AppUtility';
import ServerConfig from './ServerConfig/ServerConfig';
import StoreManager from './Store/StoreManager';
import { GROUPTYPE } from './Store/StoreMap';
import { createDemoGameLaunchContext, type GameLaunchContext } from '../../../../base/utility/GameLaunchContext';

export default class GameConfigManager {
    static instance: GameConfigManager;

    /**
     * GAMEID 存在 globalThis，避免在不同模組中被覆蓋
     */
    private static readonly GAMEID_KEY = "__APP_GAME_ID__";
    private static readonly LAUNCH_CONTEXT_KEY = '__APP_GAME_LAUNCH_CONTEXT__';

    public static get launchContext(): GameLaunchContext {
        return (globalThis as any)[GameConfigManager.LAUNCH_CONTEXT_KEY] ?? createDemoGameLaunchContext();
    }
    public static set launchContext(value: GameLaunchContext) {
        (globalThis as any)[GameConfigManager.LAUNCH_CONTEXT_KEY] = value;
    }

    public static get GAMEID(): string {
        return (globalThis as any)[GameConfigManager.GAMEID_KEY] ?? "1001";
    }
    public static set GAMEID(value: string) {
        (globalThis as any)[GameConfigManager.GAMEID_KEY] = value;
    }

    bundleList = [];
    storeManager: StoreManager;

    public static getInstance(): GameConfigManager {
        if (!GameConfigManager.instance) {
            GameConfigManager.instance = new GameConfigManager();
        }
        return GameConfigManager.instance;
    }

    constructor() {
        const urlParam = AppUtility.getURLParam("game_id");
        if (urlParam) GameConfigManager.GAMEID = urlParam;
    }
    getURLParam() {
        return {
            ID: AppUtility.getURLParam('id'),
            signature: AppUtility.getURLParam('signature'),
            cashierURL: AppUtility.getURLParam('cashier_url'),
            lobbyURL: AppUtility.getURLParam('lobby_url'),
            serviceURL: AppUtility.getURLParam('service_url'),
        };
    }
    async getHttpClientStore() {
        let httpClientStore = (await import('./Store/HttpClientStore')).default;

        return new httpClientStore({});
    }

    getLoadBundlePath() {
        return AppConfig.REMOTE ? AppUtility.getDomainName() + '/remote/' : '';
    }

    async updateServerConfig(): Promise<void> {
        // 建構子已不 eager 實例化 StoreManager（避免迷你遊戲經 GameConfigManager 意外誕生 DeviceStore、
        // 以 FIXED_HEIGHT 蓋掉 MiniGameOrientation 的 SHOW_ALL）；僅 SG 流程於此 lazy 取用
        const storeManager = StoreManager.getInstance();
        let localConfig = (await import('./ServerConfig/LocalConfig')).default;
        console.log('loclConfig = ', localConfig);
        let env = AppConfig.ENV;
        let localtion = 'HK';

        let httpClientStore = await this.getHttpClientStore();
        httpClientStore.setManager(storeManager);
        storeManager.setHttpClientStore(httpClientStore);
        let userID = AppUtility.getURLParam('id') || localConfig[localtion][env].ID;
        httpClientStore.setAPI_URL(ServerConfig[localtion][env].API_URL);
        httpClientStore.setUserID(userID);
        httpClientStore.setSignature(AppUtility.getURLParam('signature') || localConfig[localtion][env].signature);

        let abTest = AppUtility.getURLParam('ab_test');
        if (abTest === '1') {
            let trackerStore = storeManager.getTrackerStore();
            trackerStore.setGroupType(Number(userID) % 2 === 0 ? GROUPTYPE.B : GROUPTYPE.A);
        }
        storeManager.getGameStore().setServiceURL(AppUtility.getURLParam('lobby_url') || localConfig[localtion][env].lobbyURL);
        storeManager.getGameStore().setCashierURL(AppUtility.getURLParam('cashier_url') || localConfig[localtion][env].cashierURL);
        storeManager.getGameStore().setLobbyURL(AppUtility.getURLParam('lobby_url') || localConfig[localtion][env].lobbyURL);
    }
}
