    private readonly spinResultHandler = new SpinResultHandler(this);

    protected override gameInit(): void {
        this.initSharedControllers();
        this.storeManager = StoreManager.getInstance();
        AppAudio.getInstance().preloadAll(Object.values(EFFECTSMAP));
        this.loadPresentationConfig();
        this.sceneSpeedUnsubscribe = SceneSpeedStore.subscribe(GameConfigManager.GAMEID, (config) => this.onSceneSpeedChanged(config));
        this.loadReelConfig();
        installDirectorSpeedHook();

        // 狀態機（比照舊專案 GameMain.InitStates()）：註冊 NG/FG 兩個狀態，預設進入 NG
        this.registerState(GameStateKey.NG, new NGState_1001());
        this.registerState(GameStateKey.FG, new FGState_1001());
        this.changeState(GameStateKey.NG);

        // 每個 view 各自建立 model — reelCount 從 prefab 的 reelViews.length 動態取
        this.forEachView((v) => {
            const sm = new SlotMachineModel({ reelCount: v.slotMachineView.reelViews.length });
            sm.initReelModels();
            this.registerSlotMachineModel(sm);
            v.slotMachineView.init(sm);
            v.slotMachineModel = sm;
        });

        // viewH 的 model 作為向下相容欄位
        this.slotMachineModel = this.viewH.slotMachineModel;

        this.spinShortcut.bind();

        this.buyFeature.bindButtons();
        // buy feature 價格/閃爍的事件訂閱（BET_BALANCE_CHANGED/USER_BALANCE_CHANGED/GAME_SPIN_DATA_CHANGED/GAME_INIT_EXTRA_CHANGED）
        // 都搬進 BuyFeatureController 自己管理，兩邊遊戲不用再各自重複接線
        this.buyFeature.bindEvents(gameRuntimeEventBus, this.subscriptions);

        // Jackpot 初始訂閱
        this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.JACKPOT_POOL_DATA_CHANGED, (event) => {
            this.updateJackpotPoolLabels(event.jackpotPoolData);
        });

        this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.GAME_INIT_DATA_CHANGED, () => {
            const fmt = this.storeManager.getGameStore().formatAmount;
            this.jpMiniLabel.setFormatter(fmt);
            this.jpMinorLabel.setFormatter(fmt);
            this.jpMajorLabel.setFormatter(fmt);
            this.jpGrandLabel.setFormatter(fmt);
            this.storeManager.getHttpClientStore().subscribeJackpotPool();
        });

        // balance 為每幀連續變動值（跑分動畫），不適合塞進離散事件，維持原本 reaction 輪詢
        // this.registerReaction(
        //     () => this.storeManager.getModel('UserStore').balance,
        //     () => this.reevaluateBuyFeatureFlash()
        // );
        // spinData 變動時，buyFeature 閃爍條件已由 BuyFeatureController.bindEvents 自己訂閱處理，這裡只處理 spin 結果本身
        // [EVT-GAME-004] 改由 EventBus 觸發
        this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.GAME_SPIN_DATA_CHANGED, (event) => {
            if (event.spinData) this.onSpinResultReceived(event.spinData);
        });
        // buyFeature 事件綁定移至 PopupManager.getBuyFeature 載入時處理

        // 把彈窗提升到場景根節點最上層，蓋住 TemplateView
        this.reparentPopups();

        this.mainCamera = director.getScene()?.getChildByName('Canvas')?.getChildByName('Camera')?.getComponent(Camera) ?? null;

        // 直橫版切換：透過 layer 過濾，讓非當前方向的子樹完全不被 camera 渲染
        const device = StoreManager.getInstance().getDeviceStore();
        this.orientation.init(device.isLandscape);
        // [EVT-GAME-008] 裝置直橫版切換改由 EventBus 觸發
        this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED, () => {
            this.orientation.applyOrientation(device.isLandscape);
        });

        // 預設 timeScale=0 凍住 NgSymbol idle 動畫；中獎演繹由 WinAnimationController 拉到 1
        // slotMachineModel.state 屬於單一 view 實例，改訂閱該實例自己的 EventBus
        const freezeSymbolSpines = () => {
            for (const v of this.allViews) {
                v.slotMachineView?.setSymbolSpinesTimeScale(0);
            }
        };
        this.subscribeEvent(this.slotMachineModel.events, 'stateChanged', () => freezeSymbolSpines());
        freezeSymbolSpines();

        this.initReactions();
    }

    /** 讀取各自遊戲表演配置 */
    private async loadPresentationConfig(): Promise<void> {
        try {
            const asset = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadAsset(PRESENTATION_CONFIG_PATH, JsonAsset);
            PresentationStore.getInstance().setConfig(parsePresentationConfig(asset.json));
        } catch (error) {
            console.warn('[GameMain_1001] 讀取 presentation.json 失敗 使用預設值', error);
        }
    }

    /** 讀取轉輪節奏＋整體 scene 加速倍率的本地端預設值（共用同一份 jsons/reelConfig.json），
     *  分別設進 ReelTimingDebugStore／SceneSpeedStore 的 local default 層——PM 透過 DebugPanel
     *  存的 localStorage 覆寫值優先權還是更高 */
    private async loadReelConfig(): Promise<void> {
        try {
            const asset = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadAsset(REEL_CONFIG_PATH, JsonAsset);
            ReelTimingDebugStore.setLocalDefault(GameConfigManager.GAMEID, parseReelConfig(asset.json));
            SceneSpeedStore.setLocalDefault(GameConfigManager.GAMEID, parseSceneSpeedConfig(asset.json));
        } catch (error) {
            console.warn('[GameMain_1001] 讀取 reelConfig.json 失敗，沿用 Editor 基準值', error);
        }
    }

