import SlotWebSocketClient, { SlotWebSocketClientOptions } from '../../../SGEngine/Runtime/Common/SlotWebSocketClient';
import type { SlotApiBetDetailResponse, SlotApiBetHistoryResponse, SlotApiFrame, SlotApiGameInfoResponse, SlotApiGameStateResponse, SlotApiJackpotPoolSnapshot, SlotApiJackpotUnsubscribeResponse, SlotApiRequestType, SlotApiSpinResponse } from '../../../SGEngine/Runtime/Common/SlotApiTypes';
import type { AccountCredentials, AccountLoginRequest, AccountLoginResponse, AccountRegisterRequest, AccountRegisterResponse, WalletBalanceResponse, WalletTransactionRequest, WalletTransactionResponse } from './AccountApiTypes';
import { GameNet } from './GameNetHandler';
import { RestClient } from './RestClient';

export interface SlotApiClientOptions {
    httpBaseUrl: string;
    wsUrl?: string;
}
/**
 * SlotApiClient
 *
 * 目前後端 spin/game-info 等核心操作**只提供 WebSocket**（見 docs/slot-demo-frontend-api.md），
 * 沒有對應 REST 端點，所以傳輸層仍走 WebSocket（複用既有、已是純原生實作的 SlotWebSocketClient）。
 *
 * 這一層做的事是把「傳輸機制」跟「收到回應後要做什麼」拆開：
 * - 連線 / 送出請求：委派給 SlotWebSocketClient（request/response + correlation_id）。
 * - 收到回應：**額外**透過 GameNet 依 `frame.type` 分派給對應的 GameNetHandler，
 *   讓「這筆回應要更新哪個 Store／emit 哪個事件」的邏輯集中在各自的 Handler class 裡，
 *   而不是散在呼叫端（比照 SGEngine 的封包處理器模式）。
 *
 * 之後如果後端真的補上 REST 端點，只需要新增一個走 RestClient 的傳輸實作、
 * 把對應方法改接過去即可——Handler 層完全不用動。
 */

const WALLET_ADJUSTMENT_DESCRIPTION = 'devtool adjustment';
const ENV_PATH = '/v1/devtool';
/** 按接口分類方式 */
const API_PATH = {
    account: {
        register: ENV_PATH + '/register',
        login: ENV_PATH + '/login',
    },
    wallet: {
        balance: ENV_PATH + '/wallet/balance',
        deposit: ENV_PATH + '/wallet/deposit',
        withdraw: ENV_PATH + '/wallet/withdraw',
    },
} as const;

export class SlotApiClient {
    private readonly restClient: RestClient;
    private readonly gameNet = new GameNet();
    private wsClient: SlotWebSocketClient | null = null;
    private frameUnsubscribe: (() => void) | null = null;

    private token: string | null = null; // 保存給 getAuthHeaders ws 使用
    constructor(
        private readonly options: SlotApiClientOptions,
        private readonly wsClientOptions: Omit<SlotWebSocketClientOptions, 'url' | 'token'> = {}
    ) {
        this.restClient = new RestClient({
            baseUrl: options.httpBaseUrl,
            // register/login/wallet 主動請求 5xx／逾時重試2次 4xx不重試
            timeoutMs: 15000,
            retries: 2,
            retryDelayMs: 300,
            getAuthHeaders: () => ({
                ...(this.token && {
                    Authorization: `Bearer ${this.token}`,
                }),
            }),
        });
    }

    /** 註冊一個 GameNetHandler；同一個 key 只能有一個 Handler */
    public registerHandler(handler: Parameters<GameNet['register']>[0]): void {
        this.gameNet.register(handler);
    }

    // ===== REST：帳號（devtool/register、devtool/login） =====

    /** 註冊帳號 */
    public async register(credentials: AccountCredentials): Promise<AccountRegisterResponse> {
        const request: AccountRegisterRequest = {
            ...credentials,
            password_confirmation: credentials.password,
        };
        return this.restClient.post<AccountRegisterResponse>(API_PATH.account.register, request);
    }

    /** 登入並取得 WebSocket token 保存後續使用 */
    public async login(credentials: AccountCredentials): Promise<AccountLoginResponse> {
        const request: AccountLoginRequest = {
            account: credentials.account,
            password: credentials.password,
        };
        const response = await this.restClient.post<AccountLoginResponse>(API_PATH.account.login, request);
        this.token = response.token;
        return response;
    }

    // ===== REST：錢包（devtool/wallet/*） =====

    /** 取得錢包餘額 */
    public async getWalletBalance(): Promise<WalletBalanceResponse> {
        return this.restClient.get<WalletBalanceResponse>(API_PATH.wallet.balance);
    }

    /** 錢包入金 */
    public async deposit(amount: string, clientRef: string = this.createClientRef()): Promise<WalletTransactionResponse> {
        const request: WalletTransactionRequest = {
            amount,
            client_ref: clientRef,
            description: WALLET_ADJUSTMENT_DESCRIPTION,
        };
        return this.restClient.post<WalletTransactionResponse>(API_PATH.wallet.deposit, request);
    }

    /** 錢包提款 */
    public async withdraw(amount: string, clientRef: string = this.createClientRef()): Promise<WalletTransactionResponse> {
        const request: WalletTransactionRequest = {
            amount,
            client_ref: clientRef,
            description: WALLET_ADJUSTMENT_DESCRIPTION,
        };
        return this.restClient.post<WalletTransactionResponse>(API_PATH.wallet.withdraw, request);
    }

    // ===== WebSocket：連線管理 spin/game-info 等由ws提供=====

    /**
     * 建立並連線 WebSocket；連線後開始把收到的 frame 分派給已註冊的 Handler。
     * 每次呼叫都會關閉舊連線、重新建立（例如 token 過期重新登入後）。
     * token 過期重新登入自動更新保存 可直接呼叫
     */
    public async connect(token: string = this.token ?? ''): Promise<void> {
        this.token = token;
        this.close();
        this.wsClient = new SlotWebSocketClient({ url: this.options.wsUrl, token, ...this.wsClientOptions });
        this.frameUnsubscribe = this.wsClient.onFrame((frame) => this.dispatchFrame(frame));
        await this.wsClient.connect();
    }

    public close(): void {
        this.frameUnsubscribe?.();
        this.frameUnsubscribe = null;
        this.wsClient?.close();
        this.wsClient = null;
    }

    /**
     * 斷線重連成功後觸發 重送 getGameState 更新餘額 下注設定
     * SlotWebSocketClient 處理
     */
    public onReconnect(listener: () => void): () => void {
        return this.getConnectedClient().onReconnect(listener);
    }

    // ===== WebSocket：遊戲流程（spin / history / detail / state） =====

    /** 取得遊戲設定 */
    public async getGameInfo(gameCode: string, currency: string = 'TWD'): Promise<SlotApiGameInfoResponse> {
        return this.getConnectedClient().getGameInfo(gameCode, currency);
    }

    /** 取得目前遊戲狀態 */
    public async getGameState(gameCode: string, tableId?: string): Promise<SlotApiGameStateResponse> {
        return this.getConnectedClient().getGameState(gameCode, tableId);
    }

    /** 送出 Spin 請求 */
    public async spin(gameCode: string, betAmount: string, buyFeature: boolean = false): Promise<SlotApiSpinResponse> {
        return this.getConnectedClient().spin(gameCode, betAmount, buyFeature);
    }

    /** 取得下注歷史 */
    public async getBetHistory(gameCode: string, limit: number = 20, cursor: string = ''): Promise<SlotApiBetHistoryResponse> {
        return this.getConnectedClient().getBetHistory(gameCode, limit, cursor);
    }

    /** 取得單筆下注明細 */
    public async getBetDetail(operationId: string): Promise<SlotApiBetDetailResponse> {
        return this.getConnectedClient().getBetDetail(operationId);
    }

    // ===== WebSocket：Jackpot pool 總獎池

    /** Jackpot pool
     * 無訂閱不會再收到
     * */
    public async getJackpotPool(gameCode: string): Promise<SlotApiJackpotPoolSnapshot> {
        return this.getConnectedClient().getJackpotPool(gameCode);
    }

    /**
     * 訂閱 Jackpot pool 更新
     * 之後的推播無 correlation_id
     */
    public async subscribeJackpotPool(gameCode: string): Promise<SlotApiJackpotPoolSnapshot> {
        return this.getConnectedClient().subscribeJackpotPool(gameCode);
    }

    public async unsubscribeJackpotPool(gameCode: string): Promise<SlotApiJackpotUnsubscribeResponse> {
        return this.getConnectedClient().unsubscribeJackpotPool(gameCode);
    }

    /** 送出請求並等待對應回應（沿用既有的 correlation_id 機制）；回應同時也會經過 Handler 分派 */
    public async request<TPayload = unknown>(type: SlotApiRequestType, payload?: unknown, correlationId?: string): Promise<SlotApiFrame<TPayload>> {
        return this.getConnectedClient().request<TPayload>(type, payload, correlationId);
    }

    private dispatchFrame(frame: SlotApiFrame): void {
        if (!this.gameNet.has(frame.type)) return;
        this.gameNet.dispatch(frame.type, frame.payload);
    }

    /** 產生錢包交易使用的 UUID v7 */
    private createClientRef(): string {
        const timestamp = Date.now().toString(16).padStart(12, '0').slice(-12);
        const random = new Uint8Array(10);
        crypto.getRandomValues(random);

        const hex = (value: number): string => value.toString(16).padStart(2, '0');
        const version = `7${(random[0] & 0x0f).toString(16)}${hex(random[1])}`;
        const variant = `${hex((random[2] & 0x3f) | 0x80)}${hex(random[3])}`;
        const tail = Array.from(random.slice(4), hex).join('');
        return `${timestamp.slice(0, 8)}-${timestamp.slice(8)}-${version}-${variant}-${tail}`;
    }

    /** 取得已連線的 WebSocket client */
    private getConnectedClient(): SlotWebSocketClient {
        if (!this.wsClient) throw new Error('SlotApiClient: connect(token) must complete before sending game requests');
        return this.wsClient;
    }
}
