import { GameTaskFn } from '../../../0000/Core/Framework/Task/GameTask';
import { GAMESTOREMAP } from '../../../0000/Core/Runtime/Store/StoreMap';
import { SlotMachineState } from '../../../0000/SGEngine/Reel/Model/SlotMachineModel';
import type { ISlotGameMain } from '../../../0000/SGEngine/Framework/Component/ISlotGameMain';
import type { GameViewAdapter } from '../../View/GameViewAdapter';

/** 原 GameMain_1001.endSpin：把狀態機收回 IDLE，並觸發 GAME_END → NEW_GAME。 */
export function endSpin(game: ISlotGameMain<GameViewAdapter>): void {
    game.slotMachineModel.setState(SlotMachineState.IDLE);
    game.storeManager.getGameStore().setSpinStatus(GAMESTOREMAP.GAME_END);
    setTimeout(() => game.storeManager.getGameStore().setSpinStatus(GAMESTOREMAP.NEW_GAME), 0);
}

/** 薄殼 GameTaskFn：addTask() 到頂層佇列時使用。 */
export class EndSpinTask extends GameTaskFn {
    constructor(game: ISlotGameMain<GameViewAdapter>) {
        super(() => endSpin(game));
    }
}
