import { GameTaskHandler } from '../../0000/Core/Framework/Task/GameTaskHandler';
import { GameTaskQueue } from '../../0000/Core/Framework/Task/GameTaskQueue';
import { GameTaskFn, GameTaskPromise } from '../../0000/Core/Framework/Task/GameTask';
import type { SlotApiSpinResponse } from '../../0000/SGEngine/Runtime/Common/SlotApiTypes';
import type { ISlotGameMain } from '../../0000/SGEngine/Framework/Component/ISlotGameMain';
import type { GameViewAdapter } from '../View/GameViewAdapter';
import type { SlotRoundResult } from '../../0000/SGEngine/Domain/SlotRound';
import { planSpinFlow, type SpinFlowStep } from './SpinFlowPlanner';
import { SlotRoundMapper } from '../../0000/SGEngine/Runtime/Net/SlotRoundMapper';
import { resolveSlotGridLayout } from '../../0000/SGEngine/Runtime/Net/GridLayoutConfig';
import { CascadeReelsTask } from './Task/CascadeReelsTask';
import { CollectWinTask } from './Task/CollectWinTask';
import { ScatterWinTask } from './Task/ScatterWinTask';
import { FinishSpinTask } from './Task/FinishSpinTask';
import { WinAnimationTask } from './Task/WinAnimationTask';
import { EndSpinTask } from './Task/EndSpinTask';
import { EnterFreeGameTask } from './Task/EnterFreeGameTask';
import { WinFreeGamePopupTask } from './Task/WinFreeGamePopupTask';
import { PlayFreeRoundTask } from './Task/PlayFreeRoundTask';
import { ExitFreeGameTask } from './Task/ExitFreeGameTask';

/**
 * SpinResultHandler（1001）
 *
 * 比照舊專案（Cocos_2022）SGEngine 的 GameNetHandler 模式：收到 spin 回應後，
 * 在 handle() 當下解析資料、依條件動態組裝一串具名 GameTask 塞進共用佇列
 * （對應 SGNetHandler 在解析封包當下組裝 Task 鏈的模式）。entry 這裡的共用基底
 * 已改名為 GameTaskHandler（見該檔案說明）。
 *
 * 各步驟的實際演出/資料操作邏輯都已搬進 Net/Task/ 底下對應的 GameTask 子類別
 * （CascadeReelsTask/CollectWinTask/ScatterWinTask/FinishSpinTask/WinAnimationTask/
 * EndSpinTask/EnterFreeGameTask/PlayFreeRoundTask/ExitFreeGameTask），不再寫在
 * GameMain_1001 或這個檔案裡——這裡只負責「決定順序、組裝 Task」，跟 GameMain_1001
 * 之間只透過建構子傳入的 game 參考互動（沿用共用能力，如 view 存取、win-bar 等）。
 */
export class SpinResultHandler extends GameTaskHandler<SlotApiSpinResponse> {
    constructor(private readonly game: ISlotGameMain<GameViewAdapter>) {
        super(new GameTaskQueue({ debugName: '1001-cascade' }));
    }

    /**
     * 對應 SGTask_NGSpin：轉輪停止 + 消去落下迴圈。
     * 結果出來後在同一顆 Task 內依條件（有沒有倍率球／有沒有觸發免費遊戲）動態
     * addTask() 組裝後續任務——分支判斷在「解析當下」就決定好要塞哪些 Task，
     * 而不是在後面用 if/return 中斷 async 函式。
     */
    public handle(data: SlotApiSpinResponse): void {
        // const result = data.round_result.result;
        const result = data.round_result;
        // 只在這裡呼叫一次 Mapper 拿正規化結果做流程判斷（收集/FG/jackpot）；傳給各個 Task 建構子的參數維持原始 raw data 不變
        const roundResult = this.toSlotRoundResult(data);
        this.game.resetWinBar();

        const ctx: { currentCols: number[][] | null } = { currentCols: null };

        // this.addTask(new CascadeReelsTask(this.game, result.main, (cols) => (ctx.currentCols = cols)));
        this.addTask(new CascadeReelsTask(this.game, roundResult.mainSteps, (cols) => (ctx.currentCols = cols), result.presentation.main.terminal_replacements));

        // 沒有有效盤面（例如 mock 資料異常）就在這裡整串中止，比照原本 `if (!currentCols) return;`
        this.addTask(
            new GameTaskFn(() => {
                if (!ctx.currentCols) return;
                const currentCols = ctx.currentCols;

                // 是否進 FG 還要看當下盤面實際 scatter 數／玩家是否 pending buy feature，
                // 這兩個依賴即時畫面／外部狀態的條件規劃器管不到，只能在這裡先算好再傳進去
                const willEnterFreeGame = this.game.shouldEnterFreeGame(roundResult.freeSpinTriggered, currentCols);
                const steps = planSpinFlow(roundResult, willEnterFreeGame);
                this.runSpinFlowSteps(steps, roundResult, currentCols);
            })
        );
    }

    /** 依 SpinFlowPlanner 規劃好的步驟依序組裝實際 Task；這裡才是唯一會 new Task / 碰 Cocos 相關參數的地方 */
    private runSpinFlowSteps(steps: readonly SpinFlowStep[], roundResult: SlotRoundResult, currentCols: number[][]): void {
        for (const step of steps) {
            switch (step.kind) {
                case 'collectWin':
                    // 對應 SGTask_WinAnimation（倍率球收集）
                    this.addTask(new CollectWinTask(this.game, currentCols, step.mainMult, false, step.spinWin));
                    break;
                case 'scatterWin':
                    // 對應 SGTask_Scatter（觸發免費遊戲）
                    this.addTask(new ScatterWinTask(this.game, currentCols));
                    break;
                case 'finishSpin':
                    this.addTask(new FinishSpinTask(this.game, roundResult, step.spinWin));
                    break;
                case 'winAnimation':
                    this.addTask(new WinAnimationTask(this.game, step.spinWin));
                    break;
                case 'jackpot':
                    this.addTask(new GameTaskPromise(() => this.game.popups.showJackpotOnAll(step.tier, step.amount)));
                    break;
                case 'endSpin':
                    this.addTask(new EndSpinTask(this.game));
                    break;
                case 'winFreeGamePopup':
                    this.addTask(new WinFreeGamePopupTask(this.game, step.freeRoundCount));
                    break;
                case 'enterFreeGame':
                    if (roundResult.freeMultipliers.length !== step.freeRoundCount) console.warn('[FreeGame] Free and FreeMultipliers length mismatch');
                    this.addTask(new EnterFreeGameTask(this.game, step.freeRoundCount));
                    break;
                case 'playFreeRound':
                    this.addTask(new PlayFreeRoundTask(this.game, roundResult.freeRounds[step.freeRoundIndex], roundResult.freeMultipliers[step.freeRoundIndex]));
                    break;
                case 'fgDelay':
                    this.addTask(new GameTaskPromise(() => new Promise<void>((r) => this.game.scheduleOnce(r, this.game.cascadeTiming().fgDelay / 1000))));
                    break;
                case 'exitFreeGame':
                    this.addTask(new ExitFreeGameTask(this.game, roundResult, Number(roundResult.totalWin) || 0));
                    break;
            }
        }
    }

    /** SlotApi spin response 到 SlotRoundResult 的唯一入口，本檔案只用來做流程判斷，不改變傳給 Task 的 raw data */
    private toSlotRoundResult(data: SlotApiSpinResponse): SlotRoundResult {
        const configuredLayout = this.game.storeManager.getGameStore().slotLayout;
        const firstGrid = data.round_result.Main[0]?.Grid;
        const layout = firstGrid ? resolveSlotGridLayout(firstGrid, configuredLayout) : configuredLayout;
        const mapper = new SlotRoundMapper(layout);
        return mapper.toSlotRoundResult(data);
    }
}
