import { _decorator, Label } from 'cc';
import { PopupBase } from './Base/PopupBase';
import { BaseToggle } from '../../Component/BaseToggle';
import { BaseToggleGroup } from '../../Component/BaseToggleGroup';

const { ccclass, property } = _decorator;

/**
 * AutoPlayPopup — 「AUTO PLAY 選擇自動旋轉次數」彈窗。
 *
 * 6 顆局數 Toggle（10/50/100/500/1000/∞局，對應拆圖備注），由 BaseToggleGroup
 * 統一管理單選狀態，預設不選取任何一顆（defaultIndex 設為 -1）。選擇後立刻
 * 開始（confirm），但不會關閉彈窗；cancel（停止後續局數）不在這個彈窗裡，
 * 交給遊戲內的 Auto 按鈕（再次點擊時觸發）處理。關閉彈窗是另一回事，交給
 * PopupBase 既有的關閉鈕／返回鈕處理。
 */
@ccclass('AutoPlayPopup')
export class AutoPlayPopup extends PopupBase {
    @property({ type: BaseToggleGroup, tooltip: '管理 6 顆局數 Toggle 的單選群組，defaultIndex 設 -1 代表預設不選取任何一顆' })
    protected toggleGroup: BaseToggleGroup = null!;

    @property({ type: [BaseToggle], tooltip: '依序對應 countValues，數量要跟 countValues 一致' })
    protected countToggles: BaseToggle[] = [];

    @property({ tooltip: '跟 countToggles 依序對應的局數；-1 代表無限（∞）' })
    protected countValues: number[] = [10, 50, 100, 500, 1000, -1];

    /** 選取某顆 Toggle 時立即呼叫並關閉彈窗（即代表 confirm），count -1 代表無限（∞） */
    public onConfirm: ((count: number) => void) | null = null;

    private selectedIndex = -1;
    private readonly countLabels: (Label | null)[] = [];

    protected override onLoad(): void {
        super.onLoad();

        this.countLabels.length = 0;
        this.countToggles.forEach((toggle) => {
            this.countLabels.push(toggle?.node?.getChildByName('Number')?.getComponent(Label) ?? null);
        });
        this.refreshLabels();

        if (this.toggleGroup) {
            this.toggleGroup.OnToggleOn = (index) => this.selectIndex(index);
        }
    }

    /** 目前選到 countValues 的第幾個 index，-1 代表還沒選 */
    getSelectedIndex(): number {
        return this.selectedIndex;
    }

    /** 動態調整每顆 Toggle 代表的局數；長度需與 countToggles 一致，並同步更新每顆 Toggle 上顯示的數字 */
    setCountValues(values: number[]): void {
        if (values.length !== this.countToggles.length) return;
        this.countValues = values;
        this.refreshLabels();
    }

    private refreshLabels(): void {
        this.countLabels.forEach((label, index) => {
            if (!label) return;
            const value = this.countValues[index];
            label.string = value < 0 ? '∞' : String(value);
        });
    }

    /** 選取即 confirm：立即回呼；未選取（-1）不做任何事；不會關閉彈窗 */
    private selectIndex(index: number): void {
        this.selectedIndex = index;
        if (index < 0) return;

        this.onConfirm?.(this.countValues[index]);
    }
}
