import { _decorator, Button } from 'cc';
import { PopupBase } from './Base/PopupBase';
import { getSettingStore } from '../../../../../base/store/RootStoreHooks';
import { BaseToggle } from '../../Component/BaseToggle';

const { ccclass, property } = _decorator;

/**
 * SystemMenuPopup — 「SYSTEM MENU 遊戲選單」彈窗。
 *
 * 音樂／音效兩列直接讀寫 base 的 SettingStore（`musicVolume`/`soundVolume`，
 * 開＝1、關＝0，沿用既有大廳設定頁同一套音量欄位跟 localStorage persist，
 * 不另外建一套遊戲內專屬的開關狀態）。GAME INFO／遊戲記錄／離開遊戲三列
 * 純導航，各自的實際行為（開哪個彈窗/畫面）由呼叫端透過對應的 on* 回呼決定，
 * 這裡不寫死。
 */
@ccclass('SystemMenuPopup')
export class SystemMenuPopup extends PopupBase {
    @property({ type: BaseToggle, tooltip: '音樂開關' })
    protected musicToggle: BaseToggle | null = null;

    @property({ type: BaseToggle, tooltip: '音效開關' })
    protected fxToggle: BaseToggle | null = null;

    @property(Button)
    protected gameInfoButton: Button | null = null;

    @property(Button)
    protected gameHistoryButton: Button | null = null;

    @property(Button)
    protected leaveGameButton: Button | null = null;

    public onGameInfo: (() => void) | null = null;
    public onGameHistory: (() => void) | null = null;
    /** 點「離開遊戲」列之後呼叫（例如接上 LeaveConfirmPopup），彈窗本身不會自動關閉 */
    public onLeaveGame: (() => void) | null = null;

    protected override onLoad(): void {
        super.onLoad();

        // 無法互動時顯示同層的 Disable Sprite，可互動時隱藏；音樂/音效兩列永遠可互動，不受此規則管
        this.setInteractable(this.gameInfoButton, false);
        this.setInteractable(this.gameHistoryButton, false);
        this.setInteractable(this.leaveGameButton, true);

        const setting = getSettingStore();
        if (this.musicToggle) {
            this.musicToggle.setToggle((setting?.musicVolume ?? 1) > 0);
            this.musicToggle.onToggleOn = (isOn) => this.onMusicToggle(isOn);
        }
        if (this.fxToggle) {
            this.fxToggle.setToggle((setting?.soundVolume ?? 1) > 0);
            this.fxToggle.onToggleOn = (isOn) => this.onFxToggle(isOn);
        }
        if (this.gameInfoButton) {
            this.gameInfoButton.node.on(Button.EventType.CLICK, this.onGameInfoClick, this);
            this.trackDisposer(() => {
                if (this.gameInfoButton?.node?.isValid) this.gameInfoButton!.node.off(Button.EventType.CLICK, this.onGameInfoClick, this);
            });
        }
        if (this.gameHistoryButton) {
            this.gameHistoryButton.node.on(Button.EventType.CLICK, this.onGameHistoryClick, this);
            this.trackDisposer(() => {
                if (this.gameHistoryButton?.node?.isValid) this.gameHistoryButton!.node.off(Button.EventType.CLICK, this.onGameHistoryClick, this);
            });
        }
        if (this.leaveGameButton) {
            this.leaveGameButton.node.on(Button.EventType.CLICK, this.onLeaveGameClick, this);
            this.trackDisposer(() => {
                if (this.leaveGameButton?.node?.isValid) this.leaveGameButton!.node.off(Button.EventType.CLICK, this.onLeaveGameClick, this);
            });
        }
    }

    /** 統一套用「不可互動時顯示 Disable」規則；Disable 是該列節點底下同名的 Sprite 子節點 */
    private setInteractable(button: Button | null, interactable: boolean): void {
        if (!button) return;
        button.interactable = interactable;
        const disable = button.node.getChildByName('Disable');
        if (disable) disable.active = !interactable;
    }

    private onMusicToggle(isOn: boolean): void {
        getSettingStore()?.setMusicVolumeStore(isOn ? 1 : 0);
    }

    private onFxToggle(isOn: boolean): void {
        getSettingStore()?.setSoundVolumeStore(isOn ? 1 : 0);
    }

    private onGameInfoClick(): void {
        this.onGameInfo?.();
    }

    private onGameHistoryClick(): void {
        this.onGameHistory?.();
    }

    private onLeaveGameClick(): void {
        this.onLeaveGame?.();
    }
}
