import { _decorator, Component, Enum, Label } from 'cc';

const { ccclass, property, requireComponent } = _decorator;

export enum RollingNumberMode {
    Duration = 0 /** 固定時間內完成 */,
    FixedStep = 1 /** 固定間隔增減固定數值 */,
}

Enum(RollingNumberMode);

type NumberFormatter = (value: number) => string;

@ccclass('RollingNumberLabel')
@requireComponent(Label)
export class RollingNumberLabel extends Component {
    @property({
        type: RollingNumberMode,
        tooltip: ['Duration：固定時間內跑完', 'FixedStep：每隔固定時間增減固定數值'].join('\n'),
    })
    private mode = RollingNumberMode.Duration;

    @property({
        tooltip: 'Duration 模式的跑分時間（秒）',
        min: 0.01,
    })
    private duration = 0.8;

    @property({
        tooltip: 'FixedStep 模式每次增減的數值',
        min: 0.000001,
    })
    private stepAmount = 1;

    @property({
        tooltip: 'FixedStep 模式每次增減的間隔（秒）',
        min: 0.001,
    })
    private stepInterval = 0.016;

    @property({
        tooltip: '顯示的小數位數',
        min: 0,
        max: 6,
        step: 1,
    })
    private decimalPlaces = 0;

    @property({
        tooltip: '是否顯示千分位',
    })
    private useGrouping = true;

    @property({
        tooltip: '數值前綴，例如 $',
    })
    private prefix = '';

    @property({
        tooltip: '數值後綴',
    })
    private suffix = '';

    private label: Label | null = null;

    private currentValue = 0;
    private startValue = 0;
    private targetValue = 0;

    private elapsed = 0;
    private stepElapsed = 0;
    private running = false;
    private initialized = false;

    private formatter: NumberFormatter | null = null;

    protected override onLoad(): void {
        this.label = this.getComponent(Label);
    }

    protected override update(dt: number): void {
        if (!this.running) {
            return;
        }

        switch (this.mode) {
            case RollingNumberMode.Duration:
                this.updateByDuration(dt);
                break;

            case RollingNumberMode.FixedStep:
                this.updateByFixedStep(dt);
                break;
        }
    }

    protected override onDisable(): void {
        this.complete();
    }

    /**
     * 設定目標數值。
     *
     * 第一次呼叫預設直接顯示；
     * 後續呼叫會依照目前模式進行跑分。
     */
    public setValue(value: number, immediate = false): void {
        if (!Number.isFinite(value)) {
            console.warn(`[RollingNumberLabel] 收到無效數值：${value}`);
            return;
        }

        const target = this.normalize(value);

        if (!this.initialized || immediate) {
            this.applyImmediately(target);
            return;
        }

        if (this.targetValue === target) {
            return;
        }

        // 跑分途中收到新值時，從目前畫面值轉向新目標。
        this.startValue = this.currentValue;
        this.targetValue = target;

        this.elapsed = 0;
        this.stepElapsed = 0;
        this.running = this.currentValue !== this.targetValue;

        if (!this.running) {
            this.render();
        }
    }

    /**
     * 切換跑分模式。
     *
     * keepRunning = true：
     * 保留目前進度，繼續跑向原目標。
     *
     * keepRunning = false：
     * 立即完成目前跑分。
     */
    public setMode(mode: RollingNumberMode, keepRunning = true): void {
        if (this.mode === mode) {
            return;
        }

        this.mode = mode;

        if (!this.running) {
            return;
        }

        if (!keepRunning) {
            this.complete();
            return;
        }

        // 切換模式後，以目前畫面值作為新起點。
        this.startValue = this.currentValue;
        this.elapsed = 0;
        this.stepElapsed = 0;
    }

    /**
     * 設定 Duration 模式的完成時間。
     */
    public setDuration(duration: number): void {
        this.duration = Math.max(duration, 0.01);
    }

    /**
     * 設定 FixedStep 模式參數。
     */
    public setFixedStep(amount: number, interval = this.stepInterval): void {
        this.stepAmount = Math.max(Math.abs(amount), this.getMinimumUnit());

        this.stepInterval = Math.max(interval, 0.001);
    }

    /**
     * 使用專案自訂的金額格式化方法。
     */
    public setFormatter(formatter: NumberFormatter | null): void {
        this.formatter = formatter;

        if (this.initialized) {
            this.render();
        }
    }

    /**
     * 立即完成跑分。
     */
    public complete(): void {
        if (!this.initialized) {
            return;
        }

        this.currentValue = this.targetValue;
        this.startValue = this.targetValue;

        this.elapsed = 0;
        this.stepElapsed = 0;
        this.running = false;

        this.render();
    }

    public get value(): number {
        return this.currentValue;
    }

    public get target(): number {
        return this.targetValue;
    }

    public get isRunning(): boolean {
        return this.running;
    }

    public get rollingMode(): RollingNumberMode {
        return this.mode;
    }

    private updateByDuration(dt: number): void {
        this.elapsed += dt;

        const progress = Math.min(this.elapsed / Math.max(this.duration, 0.01), 1);

        // Ease Out Cubic
        const easedProgress = 1 - Math.pow(1 - progress, 3);

        this.currentValue = this.startValue + (this.targetValue - this.startValue) * easedProgress;

        if (progress >= 1) {
            this.finish();
        } else {
            this.render();
        }
    }

    private updateByFixedStep(dt: number): void {
        this.stepElapsed += dt;

        const interval = Math.max(this.stepInterval, 0.001);

        const stepCount = Math.floor(this.stepElapsed / interval);

        if (stepCount <= 0) {
            return;
        }

        this.stepElapsed -= stepCount * interval;

        const direction = Math.sign(this.targetValue - this.currentValue);

        const change = Math.max(Math.abs(this.stepAmount), this.getMinimumUnit()) * stepCount * direction;

        const nextValue = this.currentValue + change;

        if ((direction > 0 && nextValue >= this.targetValue) || (direction < 0 && nextValue <= this.targetValue) || direction === 0) {
            this.finish();
            return;
        }

        this.currentValue = this.normalize(nextValue);
        this.render();
    }

    private applyImmediately(value: number): void {
        this.initialized = true;

        this.currentValue = value;
        this.startValue = value;
        this.targetValue = value;

        this.elapsed = 0;
        this.stepElapsed = 0;
        this.running = false;

        this.render();
    }

    private finish(): void {
        this.currentValue = this.targetValue;
        this.startValue = this.targetValue;

        this.elapsed = 0;
        this.stepElapsed = 0;
        this.running = false;

        this.render();
    }

    private render(): void {
        if (!this.label?.isValid) {
            return;
        }

        const normalizedValue = this.normalize(this.currentValue);

        const text = this.formatter
            ? this.formatter(normalizedValue)
            : normalizedValue.toLocaleString('en-US', {
                  useGrouping: this.useGrouping,
                  minimumFractionDigits: this.decimalPlaces,
                  maximumFractionDigits: this.decimalPlaces,
              });

        this.label.string = `${this.prefix}${text}${this.suffix}`;
    }

    private normalize(value: number): number {
        const multiplier = Math.pow(10, this.decimalPlaces);

        return Math.round(value * multiplier) / multiplier;
    }

    private getMinimumUnit(): number {
        return Math.pow(10, -this.decimalPlaces);
    }
}
