import { _decorator, Button } from 'cc';
import { PopupBase } from './Base/PopupBase';

const { ccclass, property } = _decorator;

/**
 * LeaveConfirmPopup — 「離開目前遊戲？」確認彈窗。
 *
 * 離開／保留／重新選座三個動作各自只回呼給呼叫端，不寫死實際行為（例如
 * 「離開」要導去哪個場景、「重新選座」要開哪個彈窗，由接的那個遊戲自己決定）。
 * 三個回呼都會先關閉彈窗本身再呼叫，避免彈窗疊在後續畫面上面。
 */
@ccclass('LeaveConfirmPopup')
export class LeaveConfirmPopup extends PopupBase {
    @property(Button)
    protected leaveButton: Button = null!;

    @property(Button)
    protected keepButton: Button = null!;

    @property(Button)
    protected reselectButton: Button = null!;

    public onLeave: (() => void) | null = null;
    public onKeep: (() => void) | null = null;
    public onReselect: (() => void) | null = null;

    protected override onLoad(): void {
        super.onLoad();

        this.leaveButton.node.on(Button.EventType.CLICK, this.onLeaveClick, this);
        this.trackDisposer(() => {
            if (this.leaveButton?.node?.isValid) this.leaveButton.node.off(Button.EventType.CLICK, this.onLeaveClick, this);
        });

        this.keepButton.node.on(Button.EventType.CLICK, this.onKeepClick, this);
        this.trackDisposer(() => {
            if (this.keepButton?.node?.isValid) this.keepButton.node.off(Button.EventType.CLICK, this.onKeepClick, this);
        });

        this.reselectButton.node.on(Button.EventType.CLICK, this.onReselectClick, this);
        this.trackDisposer(() => {
            if (this.reselectButton?.node?.isValid) this.reselectButton.node.off(Button.EventType.CLICK, this.onReselectClick, this);
        });
    }

    private onLeaveClick(): void {
        this.onLeave?.();
        this.close();
    }

    private onKeepClick(): void {
        this.onKeep?.();
        this.close();
    }

    private onReselectClick(): void {
        this.onReselect?.();
        this.close();
    }
}
